"""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.

Values are parsed by a small *whitelist* AST evaluator, not by ``eval``: the profile text is
untrusted tenant input, so we only accept literal-ish expressions (numbers, strings, booleans,
``None``, lists/tuples/sets/dicts, comprehensions, arithmetic, comparisons, slicing, ternaries)
and refuse anything that could reach code — attribute access, function calls, imports, and
unknown names. Plugin selection is likewise limited to the documented ``plugins.BUILTIN_PLUGINS``
rather than importing an arbitrary module by name.
"""

from __future__ import annotations

import ast
import operator

from plugins import BUILTIN_PLUGINS

# Operators we permit inside a config value, mapped onto stdlib callables.
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.BitAnd: operator.and_,
    ast.BitOr: operator.or_,
    ast.BitXor: operator.xor,
    ast.LShift: operator.lshift,
    ast.RShift: operator.rshift,
}
_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
    ast.Invert: operator.invert,
}
_COMPARE_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}


class _UnsafeValueError(ValueError):
    """Raised when a profile value contains something the evaluator won't run."""


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).

    Values are parsed by :func:`_eval_value`, a safe AST-whitelist evaluator — not ``eval`` —
    because the text is untrusted tenant input. Plugin names are resolved against
    ``plugins.BUILTIN_PLUGINS`` only.
    """
    settings = {}
    plugin = None

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        key, sep, value = line.partition("=")
        if not sep:
            raise ValueError(f"malformed profile line (missing '='): {line!r}")
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError(f"malformed profile line (empty key): {line!r}")

        if key == "plugin":
            plugin = _select_plugin(_eval_value(value))
        else:
            settings[key] = _eval_value(value)

    return {"settings": settings, "plugin": plugin}


def _eval_value(value: str):
    """Parse a single config value into a Python object, safely.

    Accepts literal-ish expressions only (see module docstring). Raises :class:`ValueError`
    for anything the evaluator refuses.
    """
    try:
        tree = ast.parse(value, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"invalid config value {value!r}: {exc.msg}") from exc
    return _eval_node(tree.body, {})


def _select_plugin(name) -> object | None:
    """Instantiate the named transform plugin, or ``None`` when the profile sets none.

    Only ``plugins.BUILTIN_PLUGINS`` may be selected — never an arbitrary module by name.
    """
    if name is None:
        return None
    if not isinstance(name, str):
        raise ValueError(f"plugin must be a name string, got {type(name).__name__}")
    cls = BUILTIN_PLUGINS.get(name)
    if cls is None:
        raise ValueError(f"unknown plugin {name!r}; available: {sorted(BUILTIN_PLUGINS)}")
    return cls()


def _eval_node(node: ast.AST, scope: dict):
    """Evaluate a whitelisted AST node.

    ``scope`` maps comprehension variables to their current values; it is the *only* source of
    names, so no global/module/builtin lookup is ever reachable.
    """
    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.Name):
        try:
            return scope[node.id]
        except KeyError:
            raise _UnsafeValueError(f"unknown name {node.id!r} in config value") from None

    if isinstance(node, ast.BinOp):
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise _UnsafeValueError(f"operator {type(node.op).__name__} not allowed")
        return op(_eval_node(node.left, scope), _eval_node(node.right, scope))

    if isinstance(node, ast.UnaryOp):
        op = _UNARY_OPS.get(type(node.op))
        if op is None:
            raise _UnsafeValueError(f"operator {type(node.op).__name__} not allowed")
        return op(_eval_node(node.operand, scope))

    if isinstance(node, ast.BoolOp):
        values = [_eval_node(v, scope) for v in node.values]
        return all(values) if isinstance(node.op, ast.And) else any(values)

    if isinstance(node, ast.Compare):
        left = _eval_node(node.left, scope)
        for op_node, comparator in zip(node.ops, node.comparators):
            op = _COMPARE_OPS.get(type(op_node))
            if op is None:
                raise _UnsafeValueError(f"operator {type(op_node).__name__} not allowed")
            right = _eval_node(comparator, scope)
            if not op(left, right):
                return False
            left = right
        return True

    if isinstance(node, ast.IfExp):
        return (_eval_node(node.body, scope) if _eval_node(node.test, scope)
                else _eval_node(node.orelse, scope))

    if isinstance(node, ast.List):
        return [_eval_node(e, scope) for e in node.elts]

    if isinstance(node, ast.Tuple):
        return tuple(_eval_node(e, scope) for e in node.elts)

    if isinstance(node, ast.Set):
        return {_eval_node(e, scope) for e in node.elts}

    if isinstance(node, ast.Dict):
        result = {}
        for k, v in zip(node.keys, node.values):
            if k is None:  # {**other}: key is None, value is the expression to unpack
                other = _eval_node(v, scope)
                if not isinstance(other, dict):
                    raise _UnsafeValueError("dict unpacking requires a dict")
                result.update(other)
            else:
                result[_eval_node(k, scope)] = _eval_node(v, scope)
        return result

    if isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)):
        return _eval_comprehension(node, scope)

    if isinstance(node, ast.Subscript):
        return _eval_node(node.value, scope)[_eval_slice(node.slice, scope)]

    raise _UnsafeValueError(f"unsupported expression {type(node).__name__}")


def _eval_slice(node: ast.AST, scope: dict):
    if isinstance(node, ast.Slice):
        lower = _eval_node(node.lower, scope) if node.lower is not None else None
        upper = _eval_node(node.upper, scope) if node.upper is not None else None
        step = _eval_node(node.step, scope) if node.step is not None else None
        return slice(lower, upper, step)
    return _eval_node(node, scope)


def _eval_comprehension(node: ast.AST, scope: dict):
    yielded = []

    def walk(gen_index: int):
        gen = node.generators[gen_index]
        iterable = _eval_node(gen.iter, scope)
        for item in iterable:
            gen_scope = dict(scope)
            _bind(gen.target, item, gen_scope)
            if any(not _eval_node(cond, gen_scope) for cond in gen.ifs):
                continue
            if gen_index + 1 < len(node.generators):
                walk(gen_index + 1)
            elif isinstance(node, ast.DictComp):
                yielded.append((_eval_node(node.key, gen_scope),
                                _eval_node(node.value, gen_scope)))
            else:
                yielded.append(_eval_node(node.elt, gen_scope))

    walk(0)
    if isinstance(node, ast.DictComp):
        return dict(yielded)
    if isinstance(node, ast.SetComp):
        return set(yielded)
    if isinstance(node, ast.GeneratorExp):
        return tuple(yielded)
    return yielded  # ListComp


def _bind(target: ast.AST, value, scope: dict):
    if isinstance(target, ast.Name):
        scope[target.id] = value
    elif isinstance(target, (ast.Tuple, ast.List)):
        if not isinstance(value, (list, tuple)) or len(value) != len(target.elts):
            raise _UnsafeValueError("invalid comprehension target")
        for t, v in zip(target.elts, value):
            _bind(t, v, scope)
    else:
        raise _UnsafeValueError("unsupported comprehension target")

